/* The log kernel: Tang reduction, tables and Sollya polynomial, integer only.
 * Internal to src/exact/, not installed. See docs/design/transcendentals.md 2.1.
 * Bound: |p - log1p| <= 2^-101.04 (budget table in 2.1), regenerated by
 * `sollya sollya/log_kernel.sollya`. Integer only, no gcc builtin, no VLA.
 */
#pragma once

#include "fixed/fixed_int128.h"
#include "fixed/fixed_int256.h"

/* ( a * b ) >> 128 from two fixUInt256MulU128ByU64 calls (design section 0). */
static inline fixUInt128 fixLogMulHi128( fixUInt128 a, fixUInt128 b )
{
    fixUInt256 lo = fixUInt256MulU128ByU64( b, fixUInt128Lo( a ) );
    fixUInt256 hi = fixUInt256MulU128ByU64( b, fixUInt128Hi( a ) );
    fixUInt256 prod = fixUInt256Add( lo, fixUInt256Shl( hi, 64 ) );
    return fixUInt256Shr( prod, 128 ).lo;
}

