/* fixLogKernel computes S = ln(raw * 2^-16) * 2^120 in signed Q7.120 for raw > 0.
 * Design section 2.1 up to and not including the final rounding. */
static inline void fixLogKernel( int64_t raw, fixInt128* s )
{
    int msb = 0;
    uint64_t r = (uint64_t)raw;
    while ( r > 1 ) { r >>= 1; ++msb; }
    int e = msb - 16;
    uint64_t m = (uint64_t)raw << ( 62 - msb );
    int i = (int)( ( m >> 55 ) & 127 );

    fixUInt128 u = fixUInt128Sub( fixUInt128MulU64( m, kLogInv[i] ),
                                 fixUInt128Shl( fixUInt128FromU64( 1 ), 79 ) );
    fixUInt128 u128 = fixUInt128Shl( u, 49 );

    fixUInt128 w = fixUInt128Make( kLogCHi[10], kLogCLo[10] );
    for ( int k = 9; k >= 2; --k )
    {
        w = fixUInt128Sub( fixUInt128Make( kLogCHi[k], kLogCLo[k] ), fixLogMulHi128( w, u128 ) );
    }
    fixUInt128 qq = fixLogMulHi128( u128, u128 );
    fixUInt128 vv = fixLogMulHi128( qq, w );
    fixUInt128 lp = fixUInt128Sub( u128, fixUInt128Shl( vv, 1 ) );

    fixUInt256 mag1 = fixUInt256MulU128ByU64( fixUInt128Make( kLogLn2Hi, kLogLn2Lo ), (uint64_t)( e < 0 ? -e : e ) );
    fixUInt256 sh1 = fixUInt256Shr( mag1, 8 );
    fixInt128 t1 = fixInt128FromUnsigned( sh1.lo );
    if ( e < 0 ) { t1 = fixInt128Neg( t1 ); }
    fixInt128 t2 = fixInt128FromUnsigned( fixUInt128Shr( fixUInt128Make( kLogHi[i], kLogLo[i] ), 8 ) );
    fixInt128 t3 = fixInt128FromUnsigned( fixUInt128Shr( lp, 8 ) );
    *s = fixInt128Add( fixInt128Add( t1, t2 ), t3 );
}
